<script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js"></script><script src="https://cdn.jsdelivr.net/npm/docx@8.5.0/build/index.umd.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script>
<script>
const $=id=>document.getElementById(id);let current=null;
if(window.pdfjsLib)pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
$('file').addEventListener('change',async()=>{const f=$('file').files[0];if(!f)return; $('status').textContent='Reading '+f.name+'...';try{let text='';if(f.name.toLowerCase().endsWith('.txt'))text=await f.text();else if(f.name.toLowerCase().endsWith('.docx')){const a=await mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()});text=a.value;}else if(f.name.toLowerCase().endsWith('.pdf')){const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise;for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),c=await p.getTextContent();text+=c.items.map(x=>x.str).join(' ')+'\n';}}$('source').value=text;$('status').textContent='Extracted '+text.length.toLocaleString()+' characters from '+f.name+'. Review the text before generating.';}catch(e){$('status').textContent='Could not read this file. Please paste its text instead.';}});
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function render(n){current=n;let h='<h1 class="text-center mb-2">'+esc(n.title||$('topic').value||'Content Notes')+'</h1><p class="text-center muted">'+esc($('course').value)+' · '+esc($('level').value)+'</p>';if(n.overview)h+='<h2>Overview</h2><p>'+esc(n.overview)+'</p>';if(n.learning_outcomes?.length)h+='<h2>Learning Outcomes</h2><ul>'+n.learning_outcomes.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';for(const s of n.sections||[]){h+='<h2>'+esc(s.heading)+'</h2><p>'+esc(s.content)+'</p>';if(s.key_points?.length)h+='<ul>'+s.key_points.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';if(s.example)h+='<p><b>Example:</b> '+esc(s.example)+'</p>';}if(n.key_terms?.length){h+='<h2>Key Terms</h2><dl>';for(const t of n.key_terms)h+='<dt>'+esc(t.term)+'</dt><dd>'+esc(t.definition)+'</dd>';h+='</dl>';}if(n.summary)h+='<h2>Summary</h2><p>'+esc(n.summary)+'</p>';if(n.revision_questions?.length)h+='<h2>Revision Questions</h2><ol>'+n.revision_questions.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>';if(n.source_gaps?.length)h+='<h2>Points to Confirm from the Lecturer</h2><ul>'+n.source_gaps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';$('result').innerHTML=h;$('word').disabled=false;$('pdf').disabled=false;$('status').className='alert alert-success small';$('status').textContent='Notes generated. Review the content and confirm it matches the original lecture material.';}
$('notesForm').addEventListener('submit',async e=>{e.preventDefault();const source=$('source').value.trim();if(source.length<250){$('status').className='alert alert-warning small';$('status').textContent='Please add at least 250 characters of source notes.';return;}const btn=$('generate');btn.disabled=true;btn.textContent='Generating notes...';$('status').className='alert alert-info small';$('status').textContent='Analysing the lecture material and preparing your structured notes...';try{const variation=crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random();const res=await fetch('api/generate-content-notes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source,course:$('course').value,topic:$('topic').value,level:$('level').value,voice:$('voice').value,focus:$('focus').value,variation})});const data=await res.json();if(!res.ok||!data.success)throw new Error(data.message||'Generation failed');render(data.notes);}catch(err){$('status').className='alert alert-danger small';$('status').textContent=err.message;}finally{btn.disabled=false;btn.textContent='Generate my content notes →';}});
$('pdf').addEventListener('click',async()=>{if(!current)return;const opt={margin:12,filename:(current.title||'content-notes').replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.pdf',image:{type:'jpeg',quality:.96},html2canvas:{scale:1.5,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}};await html2pdf().set(opt).from($('result')).save();});
$('word').addEventListener('click',async()=>{if(!current||!window.docx)return;const {Document,Packer,Paragraph,TextRun,HeadingLevel}=docx;const children=[new Paragraph({text:current.title||'Content Notes',heading:HeadingLevel.TITLE})];const add=(head,body)=>{children.push(new Paragraph({text:head,heading:HeadingLevel.HEADING_1}));(Array.isArray(body)?body:[body]).filter(Boolean).forEach(t=>children.push(new Paragraph({children:[new TextRun(String(t))]})));};add('Overview',current.overview);add('Learning Outcomes',current.learning_outcomes);for(const s of current.sections||[]){add(s.heading,s.content);add('Key points',s.key_points);if(s.example)add('Example',s.example);}add('Key Terms',(current.key_terms||[]).map(x=>x.term+': '+x.definition));add('Summary',current.summary);add('Revision Questions',current.revision_questions);add('Points to Confirm',current.source_gaps);const doc=new Document({sections:[{children}]});const blob=await Packer.toBlob(doc);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(current.title||'content-notes').replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.docx';a.click();URL.revokeObjectURL(a.href);});
</script></body></html>